import{_ as e,o as r,c as o,a2 as a}from"./chunks/framework.BTaI8jHZ.js";const p=JSON.parse('{"title":"Ecosystem","description":"Hookshot forks, deployments, community usage, and platform presence","frontmatter":{"title":"Ecosystem","description":"Hookshot forks, deployments, community usage, and platform presence","audience":["evaluator","contributor","architect"]},"headers":[],"relativePath":"project/ecosystem.md","filePath":"project/ecosystem.md","lastUpdated":1775245966000}'),i={name:"project/ecosystem.md"};function s(n,t,l,h,d,m){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="ecosystem" tabindex="-1">Ecosystem <a class="header-anchor" href="#ecosystem" aria-label="Permalink to &quot;Ecosystem&quot;">​</a></h1><p>Matrix Hookshot exists within a broader ecosystem of forks, deployment tools, and community resources. This page maps the landscape.</p><h2 id="upstream-project" tabindex="-1">Upstream project <a class="header-anchor" href="#upstream-project" aria-label="Permalink to &quot;Upstream project&quot;">​</a></h2><p><strong>Repository:</strong> <a href="https://github.com/matrix-org/matrix-hookshot" target="_blank" rel="noreferrer">matrix-org/matrix-hookshot</a><strong>Maintainer:</strong> Element (via matrix-org GitHub org) <strong>License:</strong> Apache 2.0 <strong>Latest docs:</strong> <a href="https://matrix-org.github.io/matrix-hookshot/latest/" target="_blank" rel="noreferrer">matrix-org.github.io/matrix-hookshot</a><strong>Support room:</strong> <a href="https://matrix.to/#/#hookshot:half-shot.uk" target="_blank" rel="noreferrer">#hookshot:half-shot.uk</a></p><h3 id="activity-as-of-april-2026" tabindex="-1">Activity (as of April 2026) <a class="header-anchor" href="#activity-as-of-april-2026" aria-label="Permalink to &quot;Activity (as of April 2026)&quot;">​</a></h3><ul><li>~50 open issues, ~47 open PRs (including Renovate dependency updates)</li><li>Active development with regular releases</li><li>Originally named <code>matrix-github</code>, renamed to <code>matrix-hookshot</code> to reflect multi-service support</li></ul><h2 id="forks" tabindex="-1">Forks <a class="header-anchor" href="#forks" aria-label="Permalink to &quot;Forks&quot;">​</a></h2><p>85+ forks on GitHub. Most are personal copies. Notable active forks:</p><table tabindex="0"><thead><tr><th>Fork</th><th>Last pushed</th><th>Notes</th></tr></thead><tbody><tr><td><a href="https://github.com/HarHarLinks/matrix-hookshot" target="_blank" rel="noreferrer">HarHarLinks/matrix-hookshot</a></td><td>Jan 2026</td><td>Recent activity</td></tr><tr><td><a href="https://github.com/SpiritCroc/matrix-hookshot" target="_blank" rel="noreferrer">SpiritCroc/matrix-hookshot</a></td><td>Jan 2025</td><td>SchildiChat developer</td></tr><tr><td><a href="https://github.com/opf/matrix-hookshot" target="_blank" rel="noreferrer">opf/matrix-hookshot</a></td><td>Dec 2024</td><td>OpenProject Foundation — maintains OpenProject integration</td></tr><tr><td><a href="https://github.com/yncyrydybyl/matrix-hookshot" target="_blank" rel="noreferrer">yncyrydybyl/matrix-hookshot</a></td><td>Apr 2026</td><td>This fork — documentation restructuring</td></tr><tr><td><a href="https://github.com/globekeeper/bridges-as" target="_blank" rel="noreferrer">globekeeper/bridges-as</a></td><td>Feb 2024</td><td>Renamed, customized for their platform</td></tr><tr><td><a href="https://github.com/turt2live/matrix-hookshot" target="_blank" rel="noreferrer">turt2live/matrix-hookshot</a></td><td>Dec 2021</td><td>t2bot.io operator (historical)</td></tr><tr><td><a href="https://github.com/t2bot/matrix-github" target="_blank" rel="noreferrer">t2bot/matrix-github</a></td><td>—</td><td>Legacy pre-rename fork</td></tr></tbody></table><h3 id="code-platforms" tabindex="-1">Code platforms <a class="header-anchor" href="#code-platforms" aria-label="Permalink to &quot;Code platforms&quot;">​</a></h3><ul><li><strong>GitHub:</strong> Primary home (matrix-org/matrix-hookshot) + 85 forks</li><li><strong>Codeberg/Gitea:</strong> No official mirror. Feature request for Gitea/Forgejo support exists (<a href="https://github.com/matrix-org/matrix-hookshot/issues/304" target="_blank" rel="noreferrer">#304</a>) — would enable Codeberg integration</li><li><strong>GitLab:</strong> No known mirrors. GitLab is supported as an <em>integration target</em>, not a hosting platform for hookshot</li><li><strong>DeepWiki:</strong> AI-generated documentation at <a href="https://deepwiki.com/matrix-org/matrix-hookshot" target="_blank" rel="noreferrer">deepwiki.com/matrix-org/matrix-hookshot</a></li></ul><h2 id="deployment-methods" tabindex="-1">Deployment methods <a class="header-anchor" href="#deployment-methods" aria-label="Permalink to &quot;Deployment methods&quot;">​</a></h2><h3 id="matrix-docker-ansible-deploy" tabindex="-1">matrix-docker-ansible-deploy <a class="header-anchor" href="#matrix-docker-ansible-deploy" aria-label="Permalink to &quot;matrix-docker-ansible-deploy&quot;">​</a></h3><p>The most popular way to deploy hookshot. Part of <a href="https://github.com/spantaleev/matrix-docker-ansible-deploy" target="_blank" rel="noreferrer">spantaleev/matrix-docker-ansible-deploy</a>.</p><ul><li><strong>Config guide:</strong> <a href="https://github.com/spantaleev/matrix-docker-ansible-deploy/blob/master/docs/configuring-playbook-bridge-hookshot.md" target="_blank" rel="noreferrer">configuring-playbook-bridge-hookshot.md</a></li><li><strong>Enable:</strong> <code>matrix_hookshot_enabled: true</code> in <code>vars.yml</code></li><li>Handles config generation, registration, Docker image, reverse proxy</li><li>Actively maintained, tracks hookshot releases</li></ul><h3 id="element-server-suite-ess" tabindex="-1">Element Server Suite (ESS) <a class="header-anchor" href="#element-server-suite-ess" aria-label="Permalink to &quot;Element Server Suite (ESS)&quot;">​</a></h3><p><a href="https://element.io/en/server-suite/community" target="_blank" rel="noreferrer">Element Server Suite Community Edition</a> includes hookshot as an optional component.</p><ul><li><strong>Helm chart:</strong> <a href="https://github.com/element-hq/ess-helm" target="_blank" rel="noreferrer">element-hq/ess-helm</a></li><li><strong>Config guide:</strong> <a href="https://docs.element.io/latest/element-server-suite-pro/configuring-components/configuring-hookshot/" target="_blank" rel="noreferrer">Configuring Hookshot (ESS Pro)</a></li><li>Hookshot disabled by default — must be explicitly enabled</li><li>ESS Community is free (AGPLv3) for non-commercial use, up to ~100 users</li></ul><h3 id="nixos-nixpkgs" tabindex="-1">NixOS / nixpkgs <a class="header-anchor" href="#nixos-nixpkgs" aria-label="Permalink to &quot;NixOS / nixpkgs&quot;">​</a></h3><p>Hookshot is packaged in nixpkgs.</p><ul><li><strong>Package:</strong> <code>matrix-hookshot</code> (currently v6.0.2)</li><li><strong>Recent PRs:</strong> <a href="https://github.com/NixOS/nixpkgs/pull/376057" target="_blank" rel="noreferrer">v6.0.1 → v6.0.2 update</a>, <a href="https://github.com/NixOS/nixpkgs/pull/366107" target="_blank" rel="noreferrer">auto-update script added</a></li><li><strong>NixOS Wiki:</strong> <a href="https://nixos.wiki/wiki/Matrix" target="_blank" rel="noreferrer">Matrix page</a> mentions hookshot</li></ul><h3 id="docker-standalone" tabindex="-1">Docker (standalone) <a class="header-anchor" href="#docker-standalone" aria-label="Permalink to &quot;Docker (standalone)&quot;">​</a></h3><p>Official image: <a href="https://hub.docker.com/r/halfshot/matrix-hookshot" target="_blank" rel="noreferrer"><code>halfshot/matrix-hookshot</code></a></p><p>See <a href="./../guides/operator/installation#docker-recommended">Installation guide</a>.</p><h3 id="helm-standalone" tabindex="-1">Helm (standalone) <a class="header-anchor" href="#helm-standalone" aria-label="Permalink to &quot;Helm (standalone)&quot;">​</a></h3><p>Built-in chart at <code>helm/hookshot/</code> in the repo. See <a href="./../guides/operator/installation#helm-kubernetes">Installation guide</a>.</p><h2 id="matrix-org-coverage" tabindex="-1">matrix.org coverage <a class="header-anchor" href="#matrix-org-coverage" aria-label="Permalink to &quot;matrix.org coverage&quot;">​</a></h2><p>Hookshot appears regularly in <a href="https://matrix.org/blog/category/this-week-in-matrix/" target="_blank" rel="noreferrer">This Week in Matrix (TWIM)</a> blog posts:</p><ul><li>Multiple TWIM mentions from 2021–2026 covering releases, features, and community contributions</li><li>Key announcements: rename from matrix-github, service bots feature, encryption improvements, OpenProject support</li><li><a href="https://matrix.org/blog/2026/02/06/this-week-in-matrix-2026-02-06/" target="_blank" rel="noreferrer">TWIM 2026-02-06</a> — latest coverage</li></ul><h2 id="community-resources" tabindex="-1">Community resources <a class="header-anchor" href="#community-resources" aria-label="Permalink to &quot;Community resources&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>URL</th></tr></thead><tbody><tr><td>Support room</td><td><a href="https://matrix.to/#/#hookshot:half-shot.uk" target="_blank" rel="noreferrer">#hookshot:half-shot.uk</a></td></tr><tr><td>Official docs</td><td><a href="https://matrix-org.github.io/matrix-hookshot/latest/" target="_blank" rel="noreferrer">matrix-org.github.io/matrix-hookshot</a></td></tr><tr><td>Ansible deploy guide</td><td><a href="https://github.com/spantaleev/matrix-docker-ansible-deploy/blob/master/docs/configuring-playbook-bridge-hookshot.md" target="_blank" rel="noreferrer">configuring-playbook-bridge-hookshot.md</a></td></tr><tr><td>ESS docs</td><td><a href="https://docs.element.io/latest/element-server-suite-pro/configuring-components/configuring-hookshot/" target="_blank" rel="noreferrer">docs.element.io — Hookshot</a></td></tr><tr><td>NixOS wiki</td><td><a href="https://nixos.wiki/wiki/Matrix" target="_blank" rel="noreferrer">nixos.wiki/wiki/Matrix</a></td></tr><tr><td>Grafana dashboard</td><td><a href="https://github.com/matrix-org/matrix-hookshot/blob/main/contrib/hookshot-dashboard.json" target="_blank" rel="noreferrer">contrib/hookshot-dashboard.json</a></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><strong>Project:</strong> <a href="./roadmap">Roadmap</a> · <a href="./limitations">Limitations</a></p><p><strong>Operator:</strong> <a href="./../guides/operator/installation">Installation</a> · <a href="./../guides/operator/configuration">Configuration</a></p><p><strong>Concepts:</strong> <a href="./../understand/what-is-hookshot">What is Hookshot</a></p>',35)])])}const g=e(i,[["render",s]]);export{p as __pageData,g as default};
